import React from "react";

function ChaiList({ 
  entries = [], onDelete = () => {} }) {
  if (entries.length === 0) {
    return <div className= "subtext" >
      What feeling did that cup of chai give you?
      </div>;
  }

  return (
    <ul className= "list" >
      {entries.map((e) => (
        <li key={e.id} className= "card" >
          <div>
            {e.style}
          </div>
          <div>
            {"★".repeat(e.rating)}{"*".repeat(5 - e.rating)}
            </div>
          {e.notes && <div className="subtext">{e.notes}</div>}
          <div>
            <button onClick={() => onDelete(e.id)}>Delete</button>
          </div>
        </li>
      ))}
    </ul>
  );
}

export default ChaiList;
